{
  "name": "@axiom-lattice/cli-a2a",
  "version": "0.2.35",
  "main": "dist/index.js",
  "module": "dist/index.mjs",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.mjs",
      "require": "./dist/index.js"
    },
    "./cli-path": {
      "types": "./runtime/cli-path.d.ts",
      "import": "./runtime/cli-path.mjs",
      "require": "./runtime/cli-path.cjs"
    },
    "./package.json": "./package.json"
  },
  "bin": {
    "cli-a2a": "./dist/cli.js"
  },
  "keywords": [
    "a2a",
    "agent-to-agent",
    "opencode",
    "codex",
    "claude-code",
    "cli",
    "ai-agent"
  ],
  "author": "",
  "license": "ISC",
  "description": "Multi-provider A2A (Agent-to-Agent) CLI gateway wrapping local coding agents (OpenCode, Codex, Claude Code) as spec-compliant A2A servers",
  "dependencies": {
    "@a2a-js/sdk": "^0.3",
    "@axiom-lattice/protocols": "7.3.0"
  },
  "devDependencies": {
    "@types/express": "^5.0.3",
    "@types/jest": "^29.5.14",
    "@types/node": "^20.19.13",
    "@typescript-eslint/eslint-plugin": "^7.2.0",
    "@typescript-eslint/parser": "^7.2.0",
    "eslint": "^8.57.0",
    "jest": "^29.7.0",
    "ts-jest": "^29.4.0",
    "ts-node": "^10.9.2",
    "tsconfig-paths": "^4.2.0",
    "tsup": "^8.5.0",
    "typescript": "^5.8.2"
  },
  "peerDependencies": {
    "express": "^5.1.0",
    "uuid": "^11.1.1"
  },
  "engines": {
    "node": ">=20.10.0"
  },
  "scripts": {
    "build": "tsup src/index.ts src/cli.ts --format cjs,esm --dts --clean --sourcemap",
    "start": "node dist/cli.js",
    "dev": "tsup src/index.ts src/cli.ts --format cjs,esm --dts --watch --sourcemap",
    "lint": "eslint src",
    "test": "jest",
    "test:watch": "jest --watch",
    "test:coverage": "jest --coverage"
  }
}
